const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const root=$('#root');
const ic=(name,s=20)=>{const p={home:'<path d="M3 11.5 12 4l9 7.5M5 10.5V21h14V10.5M9 21v-6h6v6"/>',up:'<path d="M12 19V5M6 11l6-6 6 6"/>',down:'<path d="M12 5v14M6 13l6 6 6-6"/>',wallet:'<path d="M4 6.5A2.5 2.5 0 0 1 6.5 4H18v16H6.5A2.5 2.5 0 0 1 4 17.5v-11ZM4 8h14M15 13h3"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 3v4M16 3v4M3 10h18"/>',spark:'<path d="m12 3 1.5 4.5L18 9l-4.5 1.5L12 15l-1.5-4.5L6 9l4.5-1.5L12 3ZM19 15l.7 2.3L22 18l-2.3.7L19 21l-.7-2.3L16 18l2.3-.7L19 15Z"/>',gear:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1.2l2-1.5-2-3.5-2.4 1a8 8 0 0 0-2-1.2L14.2 3h-4.4l-.3 2.6a8 8 0 0 0-2 1.2l-2.4-1-2 3.5 2 1.5A7 7 0 0 0 5 12c0 .4 0 .8.1 1.2l-2 1.5 2 3.5 2.4-1a8 8 0 0 0 2 1.2l.3 2.6h4.4l.3-2.6a8 8 0 0 0 2-1.2l2.4 1 2-3.5-2-1.5c.1-.4.1-.8.1-1.2Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',bell:'<path d="M18 8a6 6 0 1 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',chev:'<path d="m9 18 6-6-6-6"/>',back:'<path d="m15 18-6-6 6-6"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18h1.4a2.3 2.3 0 0 0 0-4.6H12a1.8 1.8 0 0 1 0-3.6h3.6A5.4 5.4 0 0 0 21 7.4C21 4.8 17 3 12 3Z"/><circle cx="7.5" cy="9" r=".7"/><circle cx="10.5" cy="6.5" r=".7"/><circle cx="15" cy="7" r=".7"/>',shield:'<path d="M12 3 4.5 6v5.5c0 4.6 3.1 7.7 7.5 9.5 4.4-1.8 7.5-4.9 7.5-9.5V6L12 3Z"/><path d="m9 12 2 2 4-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10.5v6M12 7.3h.01"/>',lock:'<rect x="5" y="10" width="14" height="10" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',photo:'<rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="9" cy="10" r="2"/><path d="m4 17 5-5 4 4 3-3 4 4"/>',trash:'<path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14M10 11v6M14 11v6"/>',edit:'<path d="m4 20 4.5-1 10-10a2.1 2.1 0 0 0-3-3l-10 10L4 20ZM14 7l3 3"/>',check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="M6 6l12 12M18 6 6 18"/>',message:'<path d="M20 14.5a4 4 0 0 1-4 4H9l-5 3v-13a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4v6Z"/>'};return `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${p[name]||''}</svg>`}
const brand=()=>`<div class="brand"><img class="brand-logo-full" src="/ritmo-logo.png" alt="Ritmo"><img class="brand-icon-only" src="/ritmo-icon-192.png" alt="" aria-hidden="true"></div>`;
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const dateBR=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('pt-BR'):'—';const isoToday=()=>new Date().toISOString().slice(0,10);const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
let state={authMode:'login',data:null,page:'home',settingsSub:null,modal:null,profilePop:false,calendarDate:new Date(),movementTab:'expenses',loading:false,turnstileToken:'',turnstileWidget:null,filters:{},shortcutDraft:null};
let versionPoll=null,quoteIndex=0,quoteTimer=null,securityConfig=null;
const toast=msg=>{const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2600)};
async function api(path,opt={}){const r=await fetch(path,{credentials:'include',headers:{...(opt.body instanceof Blob?{}:{'content-type':'application/json'}),...(opt.headers||{})},...opt});let out={};try{out=await r.json()}catch{}if(!r.ok){const er=new Error(out.error||'Não foi possível concluir.');er.status=r.status;throw er}return out}
async function getSecurityConfig(){if(securityConfig)return securityConfig;try{securityConfig=await api('/api/security/config',{headers:{'cache-control':'no-cache'}})}catch{securityConfig={turnstile_sitekey:null,webauthn:true,kv:false}}return securityConfig}
async function prepareTurnstile(){const slot=$('#turnstileSlot');if(!slot)return;const cfg=await getSecurityConfig();if(!cfg.turnstile_sitekey){slot.remove();return}for(let i=0;i<80&&!window.turnstile;i++)await new Promise(r=>setTimeout(r,50));if(!window.turnstile)return;try{state.turnstileToken='';state.turnstileWidget=window.turnstile.render(slot,{sitekey:cfg.turnstile_sitekey,theme:'auto',size:'flexible',callback:t=>state.turnstileToken=t,'expired-callback':()=>state.turnstileToken='','error-callback':()=>state.turnstileToken=''})}catch{}}
const b64uToBuf=s=>{const x=String(s||'').replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(String(s||'').length/4)*4,'=');return Uint8Array.from(atob(x),c=>c.charCodeAt(0)).buffer};
const bufToB64u=buf=>btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
function creationOptions(o){return {...o,challenge:b64uToBuf(o.challenge),user:{...o.user,id:b64uToBuf(o.user.id)},excludeCredentials:(o.excludeCredentials||[]).map(c=>({...c,id:b64uToBuf(c.id)}))}}
function requestOptions(o){return {...o,challenge:b64uToBuf(o.challenge),allowCredentials:(o.allowCredentials||[]).map(c=>({...c,id:b64uToBuf(c.id)}))}}
function credentialToJSON(c){const r=c.response,out={id:c.id,rawId:bufToB64u(c.rawId),type:c.type,authenticatorAttachment:c.authenticatorAttachment||undefined,clientExtensionResults:c.getClientExtensionResults?.()||{},response:{clientDataJSON:bufToB64u(r.clientDataJSON)}};if('attestationObject'in r){out.response.attestationObject=bufToB64u(r.attestationObject);out.response.transports=r.getTransports?.()||[]}else{out.response.authenticatorData=bufToB64u(r.authenticatorData);out.response.signature=bufToB64u(r.signature);out.response.userHandle=r.userHandle?bufToB64u(r.userHandle):undefined}return out}
function applyTheme(t){const dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.classList.toggle('dark',dark);localStorage.setItem('ritmo:theme',t);document.querySelector('meta[name=theme-color]')?.setAttribute('content',dark?'#0f1113':'#f5f5f7')}
matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',()=>{if((state.data?.settings?.theme||localStorage.getItem('ritmo:theme')||'system')==='system')applyTheme('system')});
function renderAuth(error=''){
  state.data=null;clearInterval(versionPoll);clearInterval(quoteTimer);const signup=state.authMode==='signup';root.innerHTML=`<section class="auth"><div class="auth-hero"><div class="hero-orb"></div>${brand()}<div class="hero-center"><span class="eyebrow">SEU DINHEIRO, NO SEU RITMO</span><h1>Clareza para cuidar do que é <em>seu.</em></h1><p>Entradas, saídas, dívidas, haveres e metas reunidos em uma experiência leve que acompanha você no celular e no desktop.</p></div><div class="hero-pill">Sincronizado • Privado • Feito para sua rotina</div></div><div class="auth-side"><form class="auth-card" id="authForm">${brand()}<div class="auth-title"><span class="eyebrow">${signup?'PRIMEIRO ACESSO':'BEM-VINDO'}</span><h2>${signup?'Crie sua conta':'Acesse sua conta'}</h2><p>${signup?'Comece a organizar sua vida financeira.':'Continue exatamente de onde parou.'}</p></div>${error?`<div class="auth-error">${esc(error)}</div>`:''}${signup?`<label class="field">Nome<input name="name" autocomplete="name" required placeholder="Como podemos chamar você?"></label>`:''}<label class="field">Usuário<input name="username" autocomplete="username" required minlength="3" placeholder="Digite seu usuário"></label><label class="field">Senha<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="8" placeholder="Mínimo de 8 caracteres"></label>${signup?`<label class="field">Confirmar senha<input name="confirm" type="password" autocomplete="new-password" required minlength="8" placeholder="Repita sua senha"></label>`:''}<div id="turnstileSlot" class="turnstile-slot"></div><button class="btn btn-primary" type="submit">${signup?'Criar conta':'Entrar'} ${ic('chev',17)}</button><button class="auth-switch" type="button" id="authSwitch">${signup?'Já tenho uma conta':'Criar uma conta'}</button><div class="auth-note">Seus dados financeiros ficam vinculados somente à sua conta.</div></form></div></section>`;
  $('#authSwitch').onclick=()=>{state.authMode=signup?'login':'signup';renderAuth()};$('#authForm').onsubmit=authSubmit;prepareTurnstile();
}
async function authSubmit(e){e.preventDefault();const f=new FormData(e.currentTarget),username=f.get('username'),password=f.get('password'),cfg=await getSecurityConfig();if(state.authMode==='signup'&&password!==f.get('confirm'))return renderAuth('As senhas não coincidem.');if(cfg.turnstile_sitekey&&!state.turnstileToken)return toast('Conclua a verificação de segurança.');try{state.loading=true;await api(`/api/auth/${state.authMode==='signup'?'register':'login'}`,{method:'POST',body:JSON.stringify({name:f.get('name'),username,password,turnstileToken:state.turnstileToken})});await loadApp(true)}catch(err){renderAuth(err.message)}finally{state.loading=false}}
async function loadApp(afterLogin=false){try{const data=await api('/api/bootstrap');state.data=data;state.page='home';state.settingsSub=null;applyTheme(data.settings?.theme||localStorage.getItem('ritmo:theme')||'system');renderApp();startSync();if(afterLogin)toast('Tudo certo. Bem-vindo ao Ritmo.');await maybeLock()}catch(err){if(err.status===401)renderAuth();else{renderAuth('Não foi possível carregar sua conta agora.')}}}
async function syncIfNeeded(showToast=false){if(!state.data||document.hidden||!navigator.onLine)return;try{const v=await api('/api/version');if(Number(v.version)!==Number(state.data.profile.data_version)){state.data=await api('/api/bootstrap');applyTheme(state.data.settings?.theme||'system');renderApp(false);if(showToast)toast('Ritmo sincronizado.')}}catch{}}function startSync(){clearInterval(versionPoll);versionPoll=setInterval(()=>syncIfNeeded(false),120000)}
const nav=[['home','Início','home'],['income','Entradas','up'],['expenses','Saídas','down'],['debts','Dívidas','wallet'],['goals','Metas','target'],['calendar','Calendário','calendar'],['insights','Insights','spark'],['settings','Configurações','gear']];
const shortcutCatalog={expenses:['expenses','Movimentações','wallet'],debts:['debts','Dívidas','wallet'],goals:['goals','Metas','target'],calendar:['calendar','Calendário','calendar'],insights:['insights','Insights','spark'],settings:['settings','Ajustes','gear']};
const defaultShortcuts=['expenses','debts','goals'];
function mobileShortcutKeys(){let raw=state.data?.settings?.mobile_shortcuts;try{if(typeof raw==='string')raw=JSON.parse(raw)}catch{};const src=Array.isArray(raw)?raw:defaultShortcuts,a=[];for(const k of src)if(shortcutCatalog[k]&&!a.includes(k))a.push(k);for(const k of defaultShortcuts)if(a.length<3&&!a.includes(k))a.push(k);return a.slice(0,3)}
function shortcutDraftKeys(){if(!Array.isArray(state.shortcutDraft))state.shortcutDraft=[...mobileShortcutKeys()];return state.shortcutDraft}
function moveShortcutDraft(key,dir){const a=[...shortcutDraftKeys()],i=a.indexOf(key),j=i+dir;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];state.shortcutDraft=a}
function mobileBottom(){return [['home','Início','home'],...mobileShortcutKeys().map(k=>shortcutCatalog[k]),['more','Menu','menu']]}
function fabHtml(){let type='',label='';if(state.page==='income'){type='income';label='Nova entrada'}else if(state.page==='expenses'){type=(innerWidth<=760&&state.movementTab==='income')?'income':'expense';label=type==='income'?'Nova entrada':'Nova saída'}else if(state.page==='debts'){type='debt';label='Nova dívida'}else if(state.page==='goals'){type='goal';label='Nova meta'}if(!type)return '';return `<button class="fab" id="fab" data-fab-type="${type}" aria-label="${label}" title="${label}">${ic('plus',26)}</button>`}
function avatarMarkup(cls='avatar'){const p=state.data.profile;return p.avatar_key?`<img class="${cls}" src="/api/avatar?v=${p.data_version}" alt="Foto de perfil">`:`<div class="${cls}">${esc((p.name||'R')[0].toUpperCase())}</div>`}
function currentStats(){const d=state.data;const income=d.incomes.reduce((a,x)=>a+x.amount,0);const paid=d.expenses.filter(x=>x.status==='pago').reduce((a,x)=>a+x.amount,0);const pending=d.expenses.filter(x=>x.status!=='pago').reduce((a,x)=>a+x.amount,0);const debt=d.debts.reduce((a,x)=>a+x.balance,0);return {income,paid,pending,debt,balance:income-paid}}

function defaultFilter(){return {from:'',to:'',month:'',status:'all'}}
function getFilter(type){return state.filters[type]||defaultFilter()}
function filterDate(x,type){if(type==='income'||type==='expense')return x.date||'';if(type==='debt')return x.due_date||x.start_date||'';if(type==='goal')return x.deadline||'';return ''}
function filterItems(items,type){const f=getFilter(type);return items.filter(x=>{const d=filterDate(x,type);if(f.month&&(!d||!d.startsWith(f.month)))return false;if(f.from&&(!d||d<f.from))return false;if(f.to&&(!d||d>f.to))return false;if(f.status&&f.status!=='all'){if(type==='expense'){const overdue=x.status!=='pago'&&x.due_date&&x.due_date<isoToday();if(f.status==='paid'&&x.status!=='pago')return false;if(f.status==='pending'&&(x.status==='pago'||overdue))return false;if(f.status==='overdue'&&!overdue)return false}if(type==='debt'){if(f.status==='active'&&x.status==='quitada')return false;if(f.status==='done'&&x.status!=='quitada')return false}if(type==='goal'){const done=Number(x.current_amount||0)>=Number(x.target_amount||0);if(f.status==='active'&&done)return false;if(f.status==='done'&&!done)return false}}return true})}
function filterActive(type){const f=getFilter(type);return !!(f.from||f.to||f.month||(f.status&&f.status!=='all'))}
function filterAction(type){return `<button class="icon-btn head-filter-btn ${filterActive(type)?'active':''}" data-filter="${type}" aria-label="Filtrar" title="Filtrar">${ic('filter',19)}${filterActive(type)?'<span class="filter-dot"></span>':''}</button>`}
function listAction(filterType,newType,label){return innerWidth<=760?filterAction(filterType):`<button class="btn btn-primary" data-new="${newType}">${ic('plus',17)} ${label}</button>`}
function filterSummary(type,items){return filterActive(type)?`<div class="filter-summary"><span>${items.length} resultado(s) com filtro aplicado</span><button type="button" data-filter-clear="${type}">Limpar</button></div>`:''}
function filterStatusOptions(type,value){let rows=[['all','Todos']];if(type==='expense')rows.push(['paid','Pagas'],['pending','Pendentes'],['overdue','Vencidas']);if(type==='debt')rows.push(['active','Ativas'],['done','Quitadas']);if(type==='goal')rows.push(['active','Em andamento'],['done','Concluídas']);if(rows.length===1)return '';return `<label class="field full">Status<select id="filterStatus">${rows.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`}
function filterModalHtml(type){const f=getFilter(type),title={income:'Entradas',expense:'Saídas',debt:'Dívidas',goal:'Metas'}[type]||'Itens';return `<div class="modal-wrap" id="modalWrap"><div class="modal filter-modal"><div class="modal-head"><div><h3>Filtrar ${title}</h3><div class="meta">Escolha um período rápido, um mês ou um intervalo personalizado.</div></div><button class="close" id="modalClose">×</button></div><div class="filter-section"><strong>Período rápido</strong><div class="filter-chips"><button type="button" data-filter-days="7">Últimos 7 dias</button><button type="button" data-filter-days="15">Últimos 15 dias</button><button type="button" data-filter-days="30">Últimos 30 dias</button></div></div><div class="form-grid filter-grid"><label class="field full">Escolher mês<input id="filterMonth" type="month" value="${esc(f.month)}"></label><label class="field">Data inicial<input id="filterFrom" type="date" value="${esc(f.from)}"></label><label class="field">Data final<input id="filterTo" type="date" value="${esc(f.to)}"></label>${filterStatusOptions(type,f.status)}<div class="full filter-actions"><button type="button" class="btn btn-secondary" id="clearFilter">Limpar filtros</button><button type="button" class="btn btn-primary" id="applyFilter">Aplicar filtros</button></div></div></div></div>`}
function dateIsoLocal(d){const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)}
function seenNotificationIds(){let raw=state.data?.settings?.seen_notifications;try{if(typeof raw==='string')raw=JSON.parse(raw)}catch{};return Array.isArray(raw)?raw:[]}

function notifications(){const d=state.data,s=d.settings;if(!s.notifications_enabled)return[];const out=[],t=new Date();t.setHours(0,0,0,0);for(const x of d.expenses){if(x.status==='pago'||!x.due_date)continue;const due=new Date(`${x.due_date}T00:00:00`);const days=Math.ceil((due-t)/864e5);if(days<0&&s.notify_overdue)out.push({id:`over:${x.id}`,kind:'overdue',title:`${x.description} está vencida`,text:`Venceu em ${dateBR(x.due_date)} • ${money(x.amount)}`,date:x.due_date});else if(days>=0&&days<=Number(s.reminder_days||3)&&s.notify_due)out.push({id:`due:${x.id}`,kind:'due',title:`${x.description} vence ${days===0?'hoje':days===1?'amanhã':`em ${days} dias`}`,text:`${money(x.amount)} • ${dateBR(x.due_date)}`,date:x.due_date})}
  if(s.notify_goals)for(const g of d.goals){if(g.deadline){const due=new Date(`${g.deadline}T00:00:00`),days=Math.ceil((due-t)/864e5),pct=g.target_amount?g.current_amount/g.target_amount:0;if(days>=0&&days<=30&&pct<1)out.push({id:`goal:${g.id}`,kind:'goal',title:`Meta “${g.name}” se aproxima`,text:`${Math.round(pct*100)}% concluída • prazo ${dateBR(g.deadline)}`,date:g.deadline})}}
  return out.sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function unreadCount(){if(!state.data)return 0;const seen=new Set(seenNotificationIds());return notifications().filter(n=>!seen.has(n.id)).length}
function renderApp(resetScroll=true){const p=state.data.profile,collapsed=localStorage.getItem('ritmo:sidebar')==='1';root.innerHTML=`<div class="app ${collapsed?'collapsed':''}" id="app"><aside class="sidebar"><div class="side-top">${brand()}<button class="collapse" id="collapse" title="Recolher menu">${ic('chev',16)}</button></div><nav class="nav">${nav.map(n=>`<button data-page="${n[0]}" class="tone-${n[0]} ${state.page===n[0]?'active':''}">${ic(n[2])}<span>${n[1]}</span></button>`).join('')}</nav><div class="profile-side"><button class="profile-btn" id="profileBtn">${avatarMarkup()}<div class="profile-copy"><strong>${esc(p.name)}</strong><small>@${esc(p.username)}</small></div>${ic('chev',14)}</button>${state.profilePop?`<div class="profile-pop"><button data-page="profile">Editar perfil</button><button data-logout> Sair</button></div>`:''}</div></aside><header class="top-mobile"><div class="brand brand-mobile"><img class="brand-icon-mobile" src="/ritmo-icon-192.png" alt="Ritmo"></div><div class="top-actions"><button class="icon-btn" data-page="notifications">${ic('bell',19)}${unreadCount()?`<span class="bell-badge">${unreadCount()}</span>`:''}</button><div class="mobile-profile-wrap"><button id="mobileProfileBtn" class="mobile-profile-btn" aria-label="Abrir menu do perfil">${avatarMarkup()}</button>${state.profilePop?`<div class="mobile-profile-pop"><button data-page="profile">${ic('edit',15)} Editar perfil</button><button data-logout>${ic('back',15)} Sair</button></div>`:''}</div></div></header><main class="main">${pageHtml()}</main>${fabHtml()}<nav class="bottom">${mobileBottom().map(n=>`<button data-page="${n[0]}" class="tone-${n[0]} ${state.page===n[0]||(n[0]==='expenses'&&state.page==='income')||(n[0]==='more'&&['calendar','insights','settings','profile','shortcuts'].includes(state.page))?'active':''}">${ic(n[2],19)}<span>${n[1]}</span></button>`).join('')}</nav></div>${state.modal?modalHtml():''}`;
  bindApp();if(resetScroll)window.scrollTo(0,0);startQuotes();
}
function head(title,sub,action=''){const bell=state.page!=='notifications'&&innerWidth>760?`<button class="icon-btn head-notif" data-page="notifications">${ic('bell',19)}${unreadCount()?`<span class="bell-badge">${unreadCount()}</span>`:''}</button>`:'';return `<div class="page-head"><div><span class="eyebrow">RITMO</span><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${bell}${action}</div></div>`}
function pageHtml(){return `<section class="page active">${({home:homePage,income:incomePage,expenses:expensesPage,debts:debtsPage,goals:goalsPage,calendar:calendarPage,insights:insightsPage,notifications:notificationsPage,settings:settingsPage,profile:profilePage,more:morePage,shortcuts:shortcutsPage}[state.page]||homePage)()}</section>`}
function homePage(){const s=currentStats(),next=state.data.expenses.filter(x=>x.status!=='pago'&&x.due_date).sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,4);const debtPct=state.data.debts.length?Math.round(state.data.debts.filter(d=>d.status==='quitada').length/state.data.debts.length*100):0;return `${head(`Olá, ${esc(state.data.profile.name.split(' ')[0])}`, 'Aqui está o ritmo da sua vida financeira.')}<div class="balance"><div class="balance-orb"></div><small>Saldo atual</small><strong>${money(s.balance)}</strong><div class="balance-meta"><span class="pill">${ic('check',12)} Realizado</span><span>Entradas menos saídas pagas</span></div></div><div class="stats"><div class="stat"><div class="stat-top"><span class="stat-icon">${ic('up',18)}</span><span class="eyebrow">ENTRADAS</span></div><div class="stat-label">Total recebido</div><div class="stat-value">${money(s.income)}</div><div class="stat-foot">${state.data.incomes.length} lançamento(s)</div></div><div class="stat"><div class="stat-top"><span class="stat-icon">${ic('down',18)}</span><span class="eyebrow">SAÍDAS</span></div><div class="stat-label">Total pago</div><div class="stat-value">${money(s.paid)}</div><div class="stat-foot">${state.data.expenses.filter(x=>x.status==='pago').length} pago(s)</div></div><div class="stat"><div class="stat-top"><span class="stat-icon">${ic('calendar',18)}</span><span class="eyebrow">PENDENTE</span></div><div class="stat-label">Contas previstas</div><div class="stat-value">${money(s.pending)}</div><div class="stat-foot">${state.data.expenses.filter(x=>x.status!=='pago').length} pendência(s)</div></div><div class="stat"><div class="stat-top"><span class="stat-icon">${ic('wallet',18)}</span><span class="eyebrow">DÍVIDAS</span></div><div class="stat-label">Saldo devedor</div><div class="stat-value">${money(s.debt)}</div><div class="stat-foot">${debtPct}% das dívidas quitadas</div></div></div><div class="grid2"><div class="panel"><div class="panel-title"><div><h3>Próximos compromissos</h3><small>Contas pendentes com vencimento</small></div><button class="mini-btn" data-page="expenses">Ver tudo</button></div><div class="list">${next.length?next.map(x=>rowHtml(x,'expense')).join(''):`<div class="empty">Nenhuma conta pendente com vencimento. ✨</div>`}</div></div><div class="panel quote"><div><span class="quote-mark">${ic('spark',18)}</span><h3 id="quoteTitle">Seu dinheiro, no seu ritmo.</h3><p id="quoteText">Organizar é transformar pequenas decisões em mais tranquilidade.</p></div><div class="dots"><i class="active"></i><i></i><i></i></div></div></div><div class="panel" style="margin-top:13px"><div class="panel-title"><div><h3>Insight do Ritmo</h3><small>Baseado somente nos seus dados</small></div>${ic('spark',19)}</div>${insightHtml(true)}</div>`}
function rowHtml(x,type){const overdue=type==='expense'&&x.status!=='pago'&&x.due_date&&x.due_date<isoToday();return `<div class="row"><span class="row-icon ${type}-tone">${ic(type==='income'?'up':type==='expense'?'down':'wallet',17)}</span><div><strong>${esc(x.description||x.creditor||x.name)}</strong><small>${type==='expense'?`${esc(x.category)} • ${x.due_date?`vence ${dateBR(x.due_date)}`:dateBR(x.date)}`:`${esc(x.category||'')} • ${dateBR(x.date||x.start_date)}`}</small></div><div class="row-amount">${money(x.amount||x.balance||x.target_amount)}${type==='expense'?`<span class="status ${x.status==='pago'?'paid':overdue?'overdue':'pending'}">${x.status==='pago'?'Pago':overdue?'Vencido':'Pendente'}</span>`:''}</div></div>`}
function incomePage(){const items=filterItems(state.data.incomes,'income');return `${head('Entradas','Salário, renda extra e tudo que entra.',listAction('income','income','Nova entrada'))}${filterSummary('income',items)}<div class="money-list">${items.length?items.map(x=>itemMoney(x,'income')).join(''):`<div class="empty">${filterActive('income')?'Nenhuma entrada encontrada nesse período.':'Você ainda não cadastrou nenhuma entrada.'}</div>`}</div>`}
function expensePageHeader(){return `<div class="toolbar"><div class="seg"><button data-tab="expenses" class="${state.movementTab==='expenses'?'active':''}">Saídas</button><button data-tab="income" class="${state.movementTab==='income'?'active':''}">Entradas</button></div></div>`}
function expensesPage(){if(innerWidth<=760&&state.movementTab==='income'){const items=filterItems(state.data.incomes,'income');return `${head('Movimentações','Acompanhe o que entra e sai.',listAction('income','income','Nova entrada'))}${expensePageHeader()}${filterSummary('income',items)}<div class="money-list">${items.length?items.map(x=>itemMoney(x,'income')).join(''):`<div class="empty">${filterActive('income')?'Nenhuma entrada encontrada nesse período.':'Nenhuma entrada cadastrada.'}</div>`}</div>`}const items=filterItems(state.data.expenses,'expense');return `${head(innerWidth<=760?'Movimentações':'Saídas','Despesas pagas, pendentes e vencimentos.',listAction('expense','expense','Nova saída'))}${innerWidth<=760?expensePageHeader():''}${filterSummary('expense',items)}<div class="money-list">${items.length?items.map(x=>itemMoney(x,'expense')).join(''):`<div class="empty">${filterActive('expense')?'Nenhuma saída encontrada nesse período.':'Você ainda não cadastrou nenhuma saída.'}</div>`}</div>`}
function itemMoney(x,type){const overdue=type==='expense'&&x.status!=='pago'&&x.due_date&&x.due_date<isoToday();return `<article class="item-card"><div class="item-line"><div><h3>${esc(x.description)}</h3><p>${esc(x.category)} • ${dateBR(x.date)}${x.due_date?` • vence ${dateBR(x.due_date)}`:''}${x.origin==='divida'?' • vinculado à dívida':''}</p>${type==='expense'?`<span class="status ${x.status==='pago'?'paid':overdue?'overdue':'pending'}">${x.status==='pago'?'Pago':overdue?'Vencido':'Pendente'}</span>`:''}</div><span class="amount ${type==='income'?'in':'out'}">${type==='income'?'+':'−'} ${money(x.amount)}</span></div><div class="card-actions"><button class="mini-btn" data-edit="${type}" data-id="${x.id}">${ic('edit',12)} Editar</button>${type==='expense'&&x.status!=='pago'?`<button class="mini-btn" data-pay-expense="${x.id}">${ic('check',12)} Marcar pago</button>`:''}<button class="mini-btn" data-delete="${type}" data-id="${x.id}">${ic('trash',12)} Excluir</button></div></article>`}
function debtsPage(){const items=filterItems(state.data.debts,'debt');return `${head('Dívidas','Acompanhe o total, pagamentos e haveres.',listAction('debt','debt','Nova dívida'))}${filterSummary('debt',items)}<div class="big-card-grid">${items.length?items.map(debtCard).join(''):`<div class="empty">${filterActive('debt')?'Nenhuma dívida encontrada nesse período.':'Nenhuma dívida cadastrada. Quando precisar, ela aparece aqui com o saldo sendo abatido automaticamente.'}</div>`}</div>`}
function debtCard(d){const pct=d.total_amount?Math.min(100,Math.round(d.paid_amount/d.total_amount*100)):0,events=state.data.debt_events.filter(e=>e.debt_id===d.id);return `<article class="debt-card"><div class="debt-head"><div><h3>${esc(d.creditor)}</h3><div class="meta">Valor original ${money(d.total_amount)}${d.due_date?` • vence ${dateBR(d.due_date)}`:''}</div></div><span class="status ${d.status==='quitada'?'paid':'pending'}">${d.status==='quitada'?'Quitada':'Ativa'}</span></div><div class="card-number">${money(d.balance)}</div><div class="card-sub">saldo devedor atual</div><div class="progress"><i style="width:${pct}%"></i></div><div class="card-sub">${pct}% abatido</div><div class="debt-actions"><button class="btn btn-secondary" data-debt-payment="${d.id}" ${d.balance<=0?'disabled':''}>Pagamento</button><button class="btn btn-secondary" data-debt-credit="${d.id}" ${d.balance<=0?'disabled':''}>Haver</button></div>${events.length?`<div class="event-list">${events.slice(0,4).map(e=>`<div class="event"><span>${e.kind==='pagamento'?'Pagamento':'Haver'} • ${dateBR(e.date)}</span><div><strong>${money(e.amount)}</strong> <button class="mini-btn" data-delete-event="${e.id}">×</button></div></div>`).join('')}</div>`:''}<div class="card-actions"><button class="mini-btn" data-edit="debt" data-id="${d.id}">${ic('edit',12)} Editar</button><button class="mini-btn" data-delete="debt" data-id="${d.id}">${ic('trash',12)} Excluir</button></div></article>`}
function goalsPage(){const items=filterItems(state.data.goals,'goal');return `${head('Metas','Transforme planos em progresso visível.',listAction('goal','goal','Nova meta'))}${filterSummary('goal',items)}<div class="big-card-grid">${items.length?items.map(goalCard).join(''):`<div class="empty">${filterActive('goal')?'Nenhuma meta encontrada nesse período.':'Crie sua primeira meta: viagem, carro, estudos ou reserva de emergência.'}</div>`}</div>`}
function goalCard(g){const pct=Math.min(100,Math.round((g.current_amount/g.target_amount)*100||0));return `<article class="goal-card"><div class="goal-head"><div><h3>${esc(g.name)}</h3><div class="meta">${esc(g.category)}${g.deadline?` • até ${dateBR(g.deadline)}`:''}</div></div><span class="status ${pct>=100?'paid':'pending'}">${pct}%</span></div><div class="card-number">${money(g.current_amount)}</div><div class="card-sub">de ${money(g.target_amount)}</div><div class="progress"><i style="width:${pct}%"></i></div><div class="debt-actions"><button class="btn btn-secondary" data-goal-add="${g.id}">Adicionar valor</button><button class="btn btn-secondary" data-edit="goal" data-id="${g.id}">Editar</button></div><div class="card-actions"><button class="mini-btn" data-delete="goal" data-id="${g.id}">${ic('trash',12)} Excluir meta</button></div></article>`}

async function updateSystemNow(){const btn=document.querySelector('[data-system-update]');if(btn){btn.disabled=true;btn.classList.add('updating')}toast('Atualizando Ritmo...');try{if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>k.toLowerCase().includes('ritmo')).map(k=>caches.delete(k)))}if('serviceWorker'in navigator){const regs=await navigator.serviceWorker.getRegistrations();for(const reg of regs){try{await reg.update();if(reg.waiting)reg.waiting.postMessage({type:'SKIP_WAITING'})}catch{}}for(const reg of regs){try{await reg.unregister()}catch{}}}try{await fetch('/sw.js?refresh='+Date.now(),{cache:'no-store'})}catch{}const u=new URL(location.href);u.searchParams.set('_ritmo_refresh',Date.now().toString());location.replace(u.toString())}catch(e){if(btn){btn.disabled=false;btn.classList.remove('updating')}toast('Não foi possível atualizar agora.')}}
function morePage(){const update=`<button type="button" class="system-update-btn menu-update-btn" data-system-update aria-label="Atualizar Sistema" title="Atualizar Sistema"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6v5h-5"/><path d="M4 18v-5h5"/><path d="M18.4 9A7 7 0 0 0 6.2 6.2L4 8"/><path d="M5.6 15A7 7 0 0 0 17.8 17.8L20 16"/></svg></button>`;return `${head('Menu','Acesse ferramentas, conta e informações do Ritmo.',update)}<div class="more-sections"><section class="more-section"><h3>Ferramentas</h3><div class="more-grid"><button class="more-card" data-page="calendar"><span class="more-icon calendar-tone">${ic('calendar',22)}</span><div><strong>Calendário</strong><small>Movimentações e vencimentos por dia.</small></div>${ic('chev',16)}</button><button class="more-card" data-page="insights"><span class="more-icon insight-tone">${ic('spark',22)}</span><div><strong>Insights</strong><small>Entenda melhor seus dados financeiros.</small></div>${ic('chev',16)}</button><button class="more-card" data-page="shortcuts"><span class="more-icon shortcut-tone">${ic('menu',22)}</span><div><strong>Personalizar atalhos</strong><small>Escolha e ordene os atalhos da barra inferior.</small></div>${ic('chev',16)}</button></div></section><section class="more-section"><h3>Sua conta</h3><div class="more-grid"><button class="more-card" data-page="profile"><span class="more-icon">${ic('user',22)}</span><div><strong>Editar perfil</strong><small>Nome, usuário e senha.</small></div>${ic('chev',16)}</button></div></section><section class="more-section"><h3>Aplicativo</h3><div class="more-grid"><button class="more-card" data-page="settings"><span class="more-icon settings-tone">${ic('gear',22)}</span><div><strong>Configurações</strong><small>Aparência, notificações e segurança.</small></div>${ic('chev',16)}</button><button class="more-card" data-settings-open="about"><span class="more-icon info-tone">${ic('info',22)}</span><div><strong>Sobre o Ritmo</strong><small>Versão e informações do aplicativo.</small></div>${ic('chev',16)}</button><a class="more-card" href="https://wa.me/5574998029574?text=Ol%C3%A1%20Fl%C3%A1vio%2C%20eu%20gostaria%20de%20suporte%20no%20Ritmo." target="_blank" rel="noopener"><span class="more-icon support-tone">${ic('message',22)}</span><div><strong>Suporte Rocha Tech</strong><small>Fale diretamente pelo WhatsApp.</small></div>${ic('chev',16)}</a></div></section></div>`}
function shortcutsPage(){const selected=shortcutDraftKeys();return `${head('Personalizar atalhos','Marque três atalhos e escolha a ordem em que eles aparecem.')}<div class="panel shortcuts-panel"><div class="shortcut-edit-head"><div><strong>Seus atalhos</strong><small>${selected.length}/3 selecionados</small></div><span class="shortcut-counter ${selected.length===3?'ready':''}">${selected.length}/3</span></div><div class="shortcut-order">${selected.length?selected.map((k,i)=>{const n=shortcutCatalog[k];return `<div class="shortcut-order-item"><span class="drag-handle" aria-hidden="true">⋮⋮</span><span class="setting-icon tone-${n[0]}">${ic(n[2],18)}</span><div><strong>${n[1]}</strong><small>Posição ${i+1}</small></div><div class="shortcut-move"><button type="button" data-shortcut-move="${k}" data-dir="-1" ${i===0?'disabled':''} aria-label="Mover para a esquerda">‹</button><button type="button" data-shortcut-move="${k}" data-dir="1" ${i===selected.length-1?'disabled':''} aria-label="Mover para a direita">›</button></div></div>`}).join(''):'<div class="shortcut-empty">Nenhum atalho selecionado. Marque três opções abaixo.</div>'}</div><div class="shortcut-divider"></div><div class="shortcut-options-title"><strong>Escolher atalhos</strong><small>Toque para marcar ou desmarcar.</small></div><div class="shortcut-options">${Object.values(shortcutCatalog).map(n=>{const checked=selected.includes(n[0]);return `<button type="button" class="shortcut-option ${checked?'selected':''}" data-shortcut-option="${n[0]}" aria-pressed="${checked}"><span class="shortcut-checkbox">${checked?ic('check',16):''}</span><span class="setting-icon tone-${n[0]}">${ic(n[2],18)}</span><div><strong>${n[1]}</strong><small>${checked?'Selecionado':'Disponível'}</small></div></button>`}).join('')}</div><p class="shortcut-help">Início e Menu ficam fixos. Os três atalhos escolhidos são sincronizados com sua conta e aparecem nessa mesma ordem em outros aparelhos.</p><button class="btn btn-primary shortcut-save" id="saveShortcuts" type="button" ${selected.length!==3?'disabled':''}>Salvar atalhos</button></div>`}
function calendarPage(){const d=state.calendarDate,y=d.getFullYear(),m=d.getMonth();const first=new Date(y,m,1),start=new Date(y,m,1-first.getDay());let cells='';for(let i=0;i<42;i++){const x=new Date(start);x.setDate(start.getDate()+i);const iso=x.toISOString().slice(0,10),same=x.getMonth()===m,tod=iso===isoToday();const markers=[];state.data.expenses.filter(e=>(e.due_date||e.date)===iso).slice(0,3).forEach(e=>markers.push(`<i class="${e.status==='pago'?'paid':''}"></i>`));state.data.incomes.filter(e=>e.date===iso).slice(0,2).forEach(()=>markers.push('<i class="in"></i>'));cells+=`<div class="day ${same?'':'muted'} ${tod?'today':''}" data-day="${iso}">${x.getDate()}${markers.length?`<span class="cal-dots">${markers.join('')}</span>`:''}</div>`}return `${head('Calendário','Vencimentos e movimentações no tempo.')}<div class="calendar-card"><div class="cal-head"><button class="icon-btn" id="prevMonth">${ic('back',17)}</button><strong>${d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button class="icon-btn" id="nextMonth">${ic('chev',17)}</button></div><div class="cal-grid">${['D','S','T','Q','Q','S','S'].map(x=>`<b>${x}</b>`).join('')}${cells}</div></div>`}
function insightHtml(compact=false){const s=currentStats(),months=state.data.expenses.slice(0,30);let msg='Cadastre algumas movimentações para o Ritmo começar a identificar padrões úteis.';if(state.data.incomes.length||state.data.expenses.length){if(s.balance<0)msg=`Suas saídas pagas superaram as entradas em ${money(Math.abs(s.balance))}. Vale revisar os gastos já realizados antes de assumir novos compromissos.`;else if(s.pending>s.balance&&s.pending>0)msg=`Você tem ${money(s.pending)} em contas pendentes, acima do saldo realizado de ${money(s.balance)}. Priorize os vencimentos mais próximos.`;else if(s.debt>0)msg=`Seu saldo devedor total está em ${money(s.debt)}. Pagamentos e haveres registrados reduzem esse valor automaticamente.`;else msg=`Seu saldo realizado está positivo em ${money(s.balance)}. Continue acompanhando pendências e metas para manter esse ritmo.`}return `<div style="display:flex;gap:12px;align-items:flex-start"><span class="stat-icon">${ic('spark',18)}</span><div><strong style="font-size:12px">${compact?'Leitura rápida':'O que seus dados mostram agora'}</strong><p style="font-size:11px;color:var(--muted);line-height:1.6;margin:6px 0 0">${msg}</p></div></div>`}
function insightsPage(){const byCat={};for(const e of state.data.expenses.filter(x=>x.status==='pago'))byCat[e.category]=(byCat[e.category]||0)+e.amount;const top=Object.entries(byCat).sort((a,b)=>b[1]-a[1]).slice(0,5);return `${head('Insights','Raciocínio claro, baseado no que você registrou.')}<div class="panel">${insightHtml()}</div><div class="grid2" style="margin-top:13px"><div class="panel"><div class="panel-title"><div><h3>Gastos por categoria</h3><small>Somente saídas pagas</small></div></div>${top.length?top.map(([k,v])=>`<div style="padding:10px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;font-size:11px"><span>${esc(k)}</span><strong>${money(v)}</strong></div>`).join(''):`<div class="empty">Sem histórico suficiente.</div>`}</div><div class="panel"><div class="panel-title"><div><h3>Próximos vencimentos</h3><small>Para você se antecipar</small></div></div><div class="list">${notifications().filter(n=>n.kind!=='goal').slice(0,4).map(n=>`<div class="row"><span class="row-icon">${ic('bell',17)}</span><div><strong>${esc(n.title)}</strong><small>${esc(n.text)}</small></div></div>`).join('')||'<div class="empty">Nenhum alerta agora.</div>'}</div></div></div>`}
function notificationsPage(){const list=notifications(),seen=new Set(seenNotificationIds());return `${head('Notificações','Seus avisos importantes ficam aqui.',`<button class="btn btn-secondary" id="markSeen">Marcar como visto</button>`)}<div class="money-list">${list.length?list.map(n=>`<article class="item-card" style="${seen.has(n.id)?'opacity:.62':''}"><div class="item-line"><div><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></div><span class="stat-icon">${ic(n.kind==='goal'?'target':'bell',18)}</span></div></article>`).join(''):`<div class="empty">Tudo tranquilo por aqui. Nenhum aviso no momento.</div>`}</div>`}
function settingsPage(){if(state.settingsSub)return settingsSubPage(state.settingsSub);const rows=[['appearance','Aparência','Tema claro, escuro ou automático','palette'],['notifications','Notificações','Escolha quais avisos o Ritmo pode mostrar','bell'],['security','Segurança','Biometria, chave de acesso e bloqueio do aplicativo','shield']];return `${head('Configurações','Preferências e segurança do seu Ritmo.')}<div class="settings-list">${rows.map(r=>`<button class="setting-row" data-settings="${r[0]}" style="width:100%;border-top:0;border-left:0;border-right:0;background:none;text-align:left"><span class="setting-icon">${ic(r[3],18)}</span><div><strong>${r[1]}</strong><small>${r[2]}</small></div><span class="chevron">${ic('chev',16)}</span></button>`).join('')}</div>`}
function settingsSubPage(k){const s=state.data.settings,back=`<button class="subpage-back" id="settingsBack">${ic('back',15)} Configurações</button>`;if(k==='appearance')return `${back}${head('Aparência','Escolha como o Ritmo deve aparecer.')}<div class="settings-list">${[['light','Claro','Interface clara e suave'],['dark','Noturno','Escuro sem perder contraste'],['system','Automático','Acompanha o sistema']].map(x=>`<button class="setting-row" data-theme="${x[0]}" style="width:100%;border-top:0;border-left:0;border-right:0;background:none;text-align:left"><span class="setting-icon">${ic('palette',18)}</span><div><strong>${x[1]}</strong><small>${x[2]}</small></div><span>${s.theme===x[0]?ic('check',18):''}</span></button>`).join('')}</div>`;
  if(k==='notifications')return `${back}${head('Notificações','O sino mostra os avisos; aqui você decide o que pode avisar.')}<div class="settings-list">${switchRow('notifications_enabled','Ativar notificações','Permitir avisos do Ritmo',s.notifications_enabled,'bell')}${switchRow('notify_due','Contas a vencer','Avisar antes do vencimento',s.notify_due,'calendar')}${switchRow('notify_overdue','Contas vencidas','Destacar contas em atraso',s.notify_overdue,'bell')}${switchRow('notify_goals','Metas','Avisos próximos ao prazo',s.notify_goals,'target')}<div class="setting-row"><span class="setting-icon">${ic('calendar',18)}</span><div><strong>Antecedência</strong><small>Quantos dias antes avisar</small></div><select id="reminderDays" style="border:0;background:var(--surface2);border-radius:10px;padding:7px">${[1,2,3,5,7,10].map(x=>`<option value="${x}" ${Number(s.reminder_days)===x?'selected':''}>${x} dias</option>`).join('')}</select></div>${switchRow('monthly_summary','Resumo mensal','Lembrete de fechamento do mês',s.monthly_summary,'spark')}</div>`;
  if(k==='security'){const label=deviceBioLabel();const enabled=Number(state.data.security?.webauthn_count||0)>0;return `${back}${head('Segurança','Recursos disponíveis neste aparelho.')}<div class="settings-list"><div class="setting-row"><span class="setting-icon">${ic('shield',18)}</span><div><strong>Biometria e chave de acesso</strong><small id="bioHint">${deviceSecurityHint()}</small></div><button class="switch ${enabled?'on':''}" id="bioToggle"><i></i></button></div><div class="setting-row"><span class="setting-icon">${ic('lock',18)}</span><div><strong>Bloqueio automático</strong><small>Solicitar desbloqueio após inatividade</small></div><select id="lockMinutes" style="border:0;background:var(--surface2);border-radius:10px;padding:7px"><option value="0" ${Number(s.auto_lock_minutes)===0?'selected':''}>Nunca</option>${[1,5,10,15].map(x=>`<option value="${x}" ${Number(s.auto_lock_minutes)===x?'selected':''}>${x} min</option>`).join('')}</select></div><div class="setting-row"><span class="setting-icon">${ic('shield',18)}</span><div><strong>Sessão protegida</strong><small>Proteção vinculada ao ID interno da conta. Nome, usuário ou senha podem mudar sem quebrar o vínculo.</small></div>${ic('check',17)}</div></div>`}
  return `${back}${head('Sobre','Conheça o Ritmo e fale com a Rocha Tech.')}<div class="panel" style="max-width:720px"><div class="about-logo">${brand()}</div><p style="font-size:11px;line-height:1.7;color:var(--muted);margin:18px 0">O Ritmo é um produto Rocha Tech criado para tornar a gestão financeira pessoal mais clara, intuitiva e agradável no dia a dia.</p><div class="meta-row"><span>Versão</span><strong>1.0</strong></div><div class="meta-row"><span>Produto</span><strong>Rocha Tech</strong></div><a class="whatsapp" target="_blank" rel="noopener" href="https://wa.me/5574998029574?text=Ol%C3%A1%20Fl%C3%A1vio%2C%20eu%20gostaria%20de%20suporte%20no%20Ritmo.">${ic('message',18)} Suporte pelo WhatsApp</a></div>`}
function switchRow(key,title,small,val,icon){return `<div class="setting-row"><span class="setting-icon">${ic(icon,18)}</span><div><strong>${title}</strong><small>${small}</small></div><button class="switch ${Number(val)?'on':''}" data-setting-switch="${key}"><i></i></button></div>`}
function profilePage(){const p=state.data.profile;return `${head('Editar perfil','Atualize seus dados em um só lugar.')}<div class="panel profile-edit-card" style="max-width:760px"><div class="profile-edit-head">${avatarMarkup('avatar')}<div><strong>${esc(p.name)}</strong><small>@${esc(p.username)}</small></div></div><form id="profileForm" class="profile-form"><label class="field">Nome<input name="name" value="${esc(p.name)}" autocomplete="name" required></label><label class="field">Usuário<input name="username" value="${esc(p.username)}" autocomplete="username" minlength="3" required></label><label class="field full">Nova senha <span class="field-hint">opcional</span><input name="password" type="password" autocomplete="new-password" minlength="8" placeholder="Deixe em branco para manter a senha atual"></label><div class="full"><button class="btn btn-primary profile-save" type="submit">Salvar perfil</button></div></form><p class="profile-safe-note">Nome, usuário e senha continuam vinculados à mesma conta. Alterar esses dados não muda seu histórico nem sua identidade interna.</p></div>`}
function modalHtml(){const m=state.modal;if(m.type==='filter')return filterModalHtml(m.filterType);if(m.type==='quick')return `<div class="modal-wrap" id="modalWrap"><div class="modal"><div class="modal-head"><h3>Ação rápida</h3><button class="close" id="modalClose">×</button></div><div class="quick-grid">${[['income','Nova entrada','up'],['expense','Nova saída','down'],['debt','Nova dívida','wallet'],['goal','Nova meta','target']].map(x=>`<button class="quick-card" data-new="${x[0]}"><span class="setting-icon">${ic(x[2],18)}</span><strong>${x[1]}</strong></button>`).join('')}</div></div></div>`;const {type,item}=m;let title='',fields='';if(type==='income'){title=item?'Editar entrada':'Nova entrada';fields=`${input('description','Descrição',item?.description,'Ex.: Salário')}${moneyInput('amount','Valor',item?.amount)}${select('category','Categoria',['Salário','Renda extra','Venda','Reembolso','Outros'],item?.category)}${dateInput('date','Data',item?.date||isoToday())}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='expense'){title=item?'Editar saída':'Nova saída';fields=`${input('description','Descrição',item?.description,'Ex.: Aluguel')}${moneyInput('amount','Valor',item?.amount)}${select('category','Categoria',['Moradia','Alimentação','Transporte','Saúde','Lazer','Educação','Assinaturas','Dívidas','Outros'],item?.category)}${select('status','Status',['pendente','pago'],item?.status||'pendente')}${dateInput('date','Data',item?.date||isoToday())}${dateInput('due_date','Vencimento',item?.due_date||'')}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='debt'){title=item?'Editar dívida':'Nova dívida';fields=`${input('creditor','Dívida / credor',item?.creditor,'Ex.: Cartão ou empréstimo')}${moneyInput('total_amount','Valor total',item?.total_amount)}${dateInput('start_date','Data inicial',item?.start_date||isoToday())}${dateInput('due_date','Vencimento',item?.due_date||'')}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='goal'){title=item?'Editar meta':'Nova meta';fields=`${input('name','Nome da meta',item?.name,'Ex.: Viagem')}${moneyInput('target_amount','Valor alvo',item?.target_amount)}${select('category','Categoria',['Viagem','Carro','Casa','Estudos','Reserva de emergência','Personalizado'],item?.category)}${dateInput('deadline','Prazo',item?.deadline||'')}${input('notes','Observação',item?.notes,'Opcional','full')}`}
if(type==='payment'||type==='credit'){const d=state.data.debts.find(x=>x.id===m.debtId);title=type==='payment'?'Registrar pagamento':'Registrar haver';fields=`<div class="full" style="font-size:11px;color:var(--muted);margin-bottom:8px">Saldo atual: <strong>${money(d?.balance)}</strong></div>${moneyInput('amount',type==='payment'?'Valor pago':'Valor do haver')}${dateInput('date','Data',isoToday())}${input('notes','Observação','','Opcional','full')}${type==='credit'?`<label class="field full" style="display:flex;align-items:center;gap:8px"><input name="cash_received" type="checkbox" style="width:auto;margin:0"> Haver recebido em dinheiro (gera uma entrada)</label>`:''}`}
if(type==='contribution'){const g=state.data.goals.find(x=>x.id===m.goalId);title=`Adicionar à meta`;fields=`<div class="full" style="font-size:11px;color:var(--muted);margin-bottom:8px">${esc(g?.name||'Meta')} • acumulado ${money(g?.current_amount)}</div>${moneyInput('amount','Valor')}${dateInput('date','Data',isoToday())}${input('notes','Observação','','Opcional','full')}`}
return `<div class="modal-wrap" id="modalWrap"><form class="modal" id="dataForm"><div class="modal-head"><h3>${title}</h3><button class="close" type="button" id="modalClose">×</button></div><div class="form-grid">${fields}<div class="full"><button class="btn btn-primary" style="width:100%;margin-top:8px" type="submit">Salvar</button></div></div></form></div>`}
function input(name,label,value='',ph='',cls=''){return `<label class="field ${cls}">${label}<input name="${name}" value="${esc(value||'')}" placeholder="${esc(ph)}"></label>`}function moneyInput(name,label,value=''){return `<label class="field">${label}<input name="${name}" type="number" min="0" step="0.01" value="${value??''}" required placeholder="0,00"></label>`}function dateInput(name,label,value=''){return `<label class="field">${label}<input name="${name}" type="date" value="${value||''}"></label>`}function select(name,label,opts,value=''){return `<label class="field">${label}<select name="${name}">${opts.map(o=>`<option value="${o}" ${o===value?'selected':''}>${o[0].toUpperCase()+o.slice(1)}</option>`).join('')}</select></label>`}
function bindApp(){
  $$('[data-page]').forEach(b=>b.onclick=()=>{const next=b.dataset.page;if(next==='shortcuts')state.shortcutDraft=[...mobileShortcutKeys()];else if(state.page==='shortcuts')state.shortcutDraft=null;state.page=next;state.settingsSub=null;state.profilePop=false;renderApp()});$('#collapse')?.addEventListener('click',()=>{const app=$('#app'),c=app.classList.toggle('collapsed');localStorage.setItem('ritmo:sidebar',c?'1':'0')});$('#profileBtn')?.addEventListener('click',()=>{state.profilePop=!state.profilePop;renderApp(false)});$('#mobileProfileBtn')?.addEventListener('click',()=>{state.profilePop=!state.profilePop;renderApp(false)});$$('[data-logout]').forEach(b=>b.addEventListener('click',logout));$('#fab')?.addEventListener('click',e=>{const type=e.currentTarget.dataset.fabType;if(!type)return;state.modal={type};renderApp(false)});$('#modalClose')?.addEventListener('click',()=>{state.modal=null;renderApp(false)});$('#modalWrap')?.addEventListener('click',e=>{if(e.target.id==='modalWrap'){state.modal=null;renderApp(false)}});
  $$('[data-filter]').forEach(b=>b.onclick=()=>{state.modal={type:'filter',filterType:b.dataset.filter};renderApp(false)});$$('[data-filter-clear]').forEach(b=>b.onclick=()=>{state.filters[b.dataset.filter]=defaultFilter();renderApp(false)});$$('[data-settings-open]').forEach(b=>b.onclick=()=>{state.page='settings';state.settingsSub=b.dataset.settingsOpen;renderApp()});$$('[data-shortcut-option]').forEach(b=>b.onclick=()=>{const k=b.dataset.shortcutOption,a=[...shortcutDraftKeys()],i=a.indexOf(k);if(i>=0)a.splice(i,1);else{if(a.length>=3)return toast('Desmarque um atalho antes de escolher outro.');a.push(k)}state.shortcutDraft=a;renderApp(false)});$$('[data-shortcut-move]').forEach(b=>b.onclick=()=>{moveShortcutDraft(b.dataset.shortcutMove,Number(b.dataset.dir));renderApp(false)});$('#saveShortcuts')?.addEventListener('click',async()=>{const a=[...shortcutDraftKeys()];if(a.length!==3)return toast('Escolha exatamente três atalhos.');await saveSettings({mobile_shortcuts:a},'Atalhos salvos na sua conta.');state.shortcutDraft=null;state.page='more';renderApp(false)});$$('[data-filter-days]').forEach(b=>b.onclick=()=>{const days=Number(b.dataset.filterDays),end=new Date(),start=new Date();end.setHours(12,0,0,0);start.setHours(12,0,0,0);start.setDate(start.getDate()-(days-1));const f=getFilter(state.modal.filterType);f.from=dateIsoLocal(start);f.to=dateIsoLocal(end);f.month='';state.filters[state.modal.filterType]=f;renderApp(false)});$('#applyFilter')?.addEventListener('click',()=>{const type=state.modal.filterType,f=getFilter(type);f.month=$('#filterMonth')?.value||'';f.from=$('#filterFrom')?.value||'';f.to=$('#filterTo')?.value||'';f.status=$('#filterStatus')?.value||'all';if(f.from&&f.to&&f.from>f.to)return toast('A data inicial deve vir antes da final.');state.filters[type]=f;state.modal=null;renderApp(false)});$('#clearFilter')?.addEventListener('click',()=>{const type=state.modal.filterType;state.filters[type]=defaultFilter();state.modal=null;renderApp(false)});
  document.querySelector('[data-system-update]')?.addEventListener('click',updateSystemNow);
  $$('[data-new]').forEach(b=>b.onclick=()=>{state.modal={type:b.dataset.new};renderApp(false)});$$('[data-edit]').forEach(b=>{b.onclick=()=>{const type=b.dataset.edit,id=b.dataset.id,arr=type==='income'?state.data.incomes:type==='expense'?state.data.expenses:type==='debt'?state.data.debts:state.data.goals;state.modal={type,item:arr.find(x=>x.id===id)};renderApp(false)}});$$('[data-delete]').forEach(b=>b.onclick=()=>deleteItem(b.dataset.delete,b.dataset.id));$$('[data-pay-expense]').forEach(b=>b.onclick=()=>markExpensePaid(b.dataset.payExpense));$$('[data-debt-payment]').forEach(b=>b.onclick=()=>{state.modal={type:'payment',debtId:b.dataset.debtPayment};renderApp(false)});$$('[data-debt-credit]').forEach(b=>b.onclick=()=>{state.modal={type:'credit',debtId:b.dataset.debtCredit};renderApp(false)});$$('[data-delete-event]').forEach(b=>b.onclick=()=>deleteEvent(b.dataset.deleteEvent));$$('[data-goal-add]').forEach(b=>b.onclick=()=>{state.modal={type:'contribution',goalId:b.dataset.goalAdd};renderApp(false)});$('#dataForm')?.addEventListener('submit',submitData);
  $$('[data-tab]').forEach(b=>b.onclick=()=>{state.movementTab=b.dataset.tab;renderApp(false)});$('#prevMonth')?.addEventListener('click',()=>{state.calendarDate=new Date(state.calendarDate.getFullYear(),state.calendarDate.getMonth()-1,1);renderApp(false)});$('#nextMonth')?.addEventListener('click',()=>{state.calendarDate=new Date(state.calendarDate.getFullYear(),state.calendarDate.getMonth()+1,1);renderApp(false)});$$('[data-day]').forEach(b=>b.onclick=()=>dayDetails(b.dataset.day));$('#markSeen')?.addEventListener('click',()=>saveSettings({seen_notifications:notifications().map(n=>n.id)},'Avisos marcados como vistos.'));
  $$('[data-settings]').forEach(b=>b.onclick=()=>{state.settingsSub=b.dataset.settings;renderApp()});$('#settingsBack')?.addEventListener('click',()=>{state.settingsSub=null;renderApp()});$$('[data-theme]').forEach(b=>b.onclick=()=>saveSettings({theme:b.dataset.theme}));$$('[data-setting-switch]').forEach(b=>b.onclick=()=>saveSettings({[b.dataset.settingSwitch]:b.classList.contains('on')?0:1}));$('#reminderDays')?.addEventListener('change',e=>saveSettings({reminder_days:Number(e.target.value)}));$('#lockMinutes')?.addEventListener('change',e=>saveSettings({auto_lock_minutes:Number(e.target.value)}));$('#bioToggle')?.addEventListener('click',toggleBiometric);$('#profileForm')?.addEventListener('submit',saveProfile);
}
async function mutate(path,opt,msg){try{await api(path,opt);state.data=await api('/api/bootstrap');applyTheme(state.data.settings.theme);state.modal=null;renderApp(false);toast(msg||'Salvo com sucesso.')}catch(e){toast(e.message)}}
async function submitData(e){e.preventDefault();const f=new FormData(e.currentTarget),o=Object.fromEntries(f.entries()),m=state.modal;for(const k of ['amount','total_amount','target_amount'])if(k in o)o[k]=Number(o[k]);if(m.type==='credit')o.cash_received=f.get('cash_received')==='on';let path='',method='POST';if(['income','expense','debt','goal'].includes(m.type)){const plural={income:'incomes',expense:'expenses',debt:'debts',goal:'goals'}[m.type];path=`/api/${plural}${m.item?`/${m.item.id}`:''}`;method=m.item?'PATCH':'POST'}else if(m.type==='payment')path=`/api/debts/${m.debtId}/payment`;else if(m.type==='credit')path=`/api/debts/${m.debtId}/credit`;else if(m.type==='contribution')path=`/api/goals/${m.goalId}/contributions`;await mutate(path,{method,body:JSON.stringify(o)},'Atualizado no seu Ritmo.')}
async function deleteItem(type,id){if(!confirm('Excluir este item?'))return;const plural={income:'incomes',expense:'expenses',debt:'debts',goal:'goals'}[type];await mutate(`/api/${plural}/${id}`,{method:'DELETE'},'Item excluído.')}
async function deleteEvent(id){if(!confirm('Remover este abatimento? O saldo da dívida será recalculado.'))return;await mutate(`/api/debt-events/${id}`,{method:'DELETE'},'Dívida recalculada.')}
async function markExpensePaid(id){const x=state.data.expenses.find(e=>e.id===id);if(!x)return;await mutate(`/api/expenses/${id}`,{method:'PATCH',body:JSON.stringify({...x,status:'pago'})},'Conta marcada como paga.')}
async function saveSettings(patch,msg='Preferência salva.'){try{await api('/api/settings',{method:'PATCH',body:JSON.stringify(patch)});state.data.settings={...state.data.settings,...patch};state.data.profile.data_version=Number(state.data.profile.data_version||0)+1;applyTheme(state.data.settings.theme||'system');renderApp(false);toast(msg)}catch(e){toast(e.message)}}
async function saveProfile(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget).entries());await mutate('/api/profile',{method:'PATCH',body:JSON.stringify(o)},'Perfil atualizado sem perder sua conta.')}
async function uploadAvatar(e){const file=e.target.files?.[0];if(!file)return;try{await api('/api/avatar',{method:'PUT',body:file,headers:{'content-type':file.type}});state.data=await api('/api/bootstrap');renderApp(false);toast('Foto atualizada.')}catch(err){toast(err.message)}}
async function logout(){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}state.data=null;renderAuth()}
function dayDetails(day){const ex=state.data.expenses.filter(x=>(x.due_date||x.date)===day),inc=state.data.incomes.filter(x=>x.date===day);state.modal={type:'quick'};renderApp(false);const modal=$('.modal');if(modal)modal.innerHTML=`<div class="modal-head"><div><h3>${dateBR(day)}</h3><div class="meta">Movimentações deste dia</div></div><button class="close" id="modalClose">×</button></div><div class="list">${[...inc.map(x=>rowHtml(x,'income')),...ex.map(x=>rowHtml(x,'expense'))].join('')||'<div class="empty">Nenhum lançamento neste dia.</div>'}</div>`;$('#modalClose').onclick=()=>{state.modal=null;renderApp(false)}}
function startQuotes(){clearInterval(quoteTimer);if(!$('#quoteTitle'))return;const q=[['Seu dinheiro, no seu ritmo.','Organizar é transformar pequenas decisões em mais tranquilidade.'],['Constância vale mais que pressa.','Acompanhar um pouco por dia deixa suas escolhas mais claras.'],['Um passo de cada vez também é progresso.','Metas ficam mais leves quando você enxerga cada evolução.']];quoteTimer=setInterval(()=>{quoteIndex=(quoteIndex+1)%q.length;const t=$('#quoteTitle'),p=$('#quoteText');if(t)t.textContent=q[quoteIndex][0];if(p)p.textContent=q[quoteIndex][1];$$('.dots i').forEach((x,i)=>x.classList.toggle('active',i===quoteIndex))},4300)}
function deviceBioLabel(){const ua=navigator.userAgent;if(/iPhone|iPad|iPod/i.test(ua))return 'Face ID / Touch ID';if(/Android/i.test(ua))return 'biometria ou chave de acesso do aparelho';if(/Windows/i.test(ua))return 'Windows Hello';if(/Mac/i.test(ua))return 'Touch ID / desbloqueio do Mac';return 'desbloqueio seguro do aparelho'}function deviceSecurityHint(){const ua=navigator.userAgent;if(/iPhone|iPad|iPod/i.test(ua))return 'Usa o fluxo nativo da Apple com Face ID/Touch ID e o provedor de chaves de acesso configurado no aparelho.';if(/SamsungBrowser|SM-[A-Z0-9]+/i.test(ua))return 'Usa o provedor de credenciais configurado no seu Samsung, como Samsung Pass quando ele estiver definido no aparelho.';if(/Android/i.test(ua))return 'Usa a biometria e o provedor de credenciais configurado no Android. O Ritmo não acessa diretamente sua digital.';if(/Windows/i.test(ua))return 'Usa o Windows Hello e o autenticador configurado neste computador.';if(/Mac/i.test(ua))return 'Usa Touch ID ou o desbloqueio seguro configurado no Mac.';return 'Usa o autenticador seguro disponibilizado pelo próprio aparelho.'}
async function platformBioAvailable(){try{return !!(window.PublicKeyCredential&&await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable())}catch{return false}}
const bioKey=()=>`ritmo:bio:${state.data.profile.id}`;
async function toggleBiometric(){const enabled=Number(state.data.security?.webauthn_count||0)>0;if(enabled){if(!confirm(`Desativar ${deviceBioLabel()} para esta conta?`))return;try{await api('/api/webauthn/credentials',{method:'DELETE',body:'{}'});localStorage.removeItem(`${bioKey()}:verified`);state.data=await api('/api/bootstrap');renderApp(false);toast('Proteção do aparelho desativada.')}catch(e){toast(e.message)}return}if(!await platformBioAvailable()){toast('Este aparelho ou navegador não disponibilizou o autenticador seguro do sistema.');return}try{const options=await api('/api/webauthn/register/options',{method:'POST',body:'{}'});const cred=await navigator.credentials.create({publicKey:creationOptions(options)});await api('/api/webauthn/register/verify',{method:'POST',body:JSON.stringify({credential:credentialToJSON(cred)})});localStorage.setItem(`${bioKey()}:verified`,String(Date.now()));state.data=await api('/api/bootstrap');renderApp(false);toast('Proteção do aparelho ativada com segurança.')}catch(e){toast(e.message||'Não foi possível ativar a proteção neste aparelho.')}}
async function maybeLock(){if(!state.data)return;const enabled=Number(state.data.security?.webauthn_count||0)>0,mins=Number(state.data.settings.auto_lock_minutes||0);if(!enabled||mins===0)return;const last=Number(localStorage.getItem(`${bioKey()}:verified`)||0);if(Date.now()-last<mins*60000)return;await showLock()}
async function showLock(){if($('#lock'))return;root.insertAdjacentHTML('beforeend',`<div class="lock" id="lock"><div class="lock-card">${brand()}<h2>Ritmo bloqueado</h2><p>Use ${deviceBioLabel()} para continuar nesta conta.</p><button class="btn btn-primary" id="unlockBtn">${ic('shield',18)} Desbloquear</button><button class="auth-switch" id="lockLogout">Usar outra conta</button></div></div>`);$('#unlockBtn').onclick=unlockBio;$('#lockLogout').onclick=logout}
async function unlockBio(){try{const options=await api('/api/webauthn/auth/options',{method:'POST',body:'{}'});const cred=await navigator.credentials.get({publicKey:requestOptions(options)});await api('/api/webauthn/auth/verify',{method:'POST',body:JSON.stringify({credential:credentialToJSON(cred)})});localStorage.setItem(`${bioKey()}:verified`,String(Date.now()));$('#lock')?.remove();toast('Desbloqueado com segurança.')}catch(e){toast(e.message||'Não foi possível confirmar o desbloqueio.')}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){maybeLock();syncIfNeeded(false)}});window.addEventListener('online',()=>syncIfNeeded(false));
(async()=>{if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});applyTheme(localStorage.getItem('ritmo:theme')||'system');try{const d=await api('/api/bootstrap');state.data=d;applyTheme(d.settings?.theme||'system');renderApp();startSync();await maybeLock()}catch(e){renderAuth()}})();

if('serviceWorker'in navigator){window.addEventListener('load',async()=>{try{const reg=await navigator.serviceWorker.getRegistration();if(reg)await reg.update()}catch{}})}
